<script setup lang="ts">
import {ref} from 'vue'
import {useRoute} from 'vue-router'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../api/http'
import {useAuthenticationStore} from '../stores/authentication'
import AppointmentReviewQueue from './AppointmentReviewQueue.vue'
const props=defineProps<{action:'attend'|'cancel'|'no-show'}>(),api=createProtectedClient(),auth=useAuthenticationStore(),route=useRoute()
const id=ref(typeof route.query.appointmentId==='string'?route.query.appointmentId:''),appointment=ref<components['schemas']['AppointmentView']|null>(null),patient=ref<components['schemas']['PatientView']|null>(null),clinic=ref(''),number=ref(''),birth=ref(''),service=ref(''),person=ref(false),reference=ref(''),reason=ref(''),busy=ref(false),error=ref(''),notice=ref(''),unknown=ref(false)
const queueRevision=ref(0),absenceConfirmed=ref(false)
const titles={attend:'确认到诊',cancel:'核实患者取消','no-show':'核实登记爽约'}
const buttons={attend:'确认本人到诊',cancel:'确认登记患者取消','no-show':'确认核实未到诊并登记爽约'}
const operation=()=>props.action==='attend'?'attendAppointment':props.action==='cancel'?'cancelAppointment':'markNoShow'
let pending:PreparedCommand|undefined
const labels:Record<string,string>={SCHEDULED:'待就诊',IN_PROGRESS:'诊疗中',COMPLETED:'已完成治疗',INVOICED:'已结算',CANCELLED:'已取消'}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({USE_NO_SHOW_REVIEW:'时隙已结束，请转爽约核实流程。',USE_CLINIC_RESCHEDULING:'班次已停诊，请转停诊处理流程。',SCHEDULE_SUSPENDED:'班次已停诊，不能确认到诊。',SLOT_NOT_ENDED:'预约时隙尚未结束，不能登记爽约。',APPOINTMENT_STATE_CONFLICT:'预约状态已改变，请重新读取。',PATIENT_VERIFICATION_REQUIRED:'核验引用无效，请重新核实本人及实际服务诊所。'}[failure.code]??`操作未完成：${failure.code}`):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){patient.value=null;appointment.value=null;reference.value='';await auth.ensure()}else if(failure instanceof ApiFailure && failure.code==='APPOINTMENT_STATE_CONFLICT' && auth.canAccess('RECEPTION','getAppointment')){try{appointment.value=await api.get(`/api/v1/appointments/${encodeURIComponent(id.value)}`)}catch{appointment.value=null}}}
async function read(){if(!id.value)return;busy.value=true;error.value='';reference.value='';patient.value=null;try{appointment.value=await api.get(`/api/v1/appointments/${encodeURIComponent(id.value)}`);clinic.value=appointment.value!.clinic_id}catch(failure){await failed(failure)}finally{busy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';const operation=pending.operation;try{const result=await api.execute<components['schemas']['AppointmentView']|components['schemas']['PatientLookupResult']>(pending);if(operation==='lookupPatient'){const proof=result.data as components['schemas']['PatientLookupResult'];if(appointment.value && proof.patient.patient_id!==appointment.value.patient_id){patient.value=null;reference.value='';throw new ApiFailure(422,'PATIENT_VERIFICATION_MISMATCH')}patient.value=proof.patient;reference.value=proof.verification_reference;notice.value='本人及本次服务依据已核验。'}else{appointment.value=result.data as components['schemas']['AppointmentView'];queueRevision.value++;notice.value=operation==='attendAppointment'?'已确认到诊，当前为诊疗中。':operation==='markNoShow'?'已核实登记爽约，原预约及历史保留。':'已登记患者取消，原预约及历史保留。'}pending=undefined;unknown.value=false}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果尚未确认，请查询原请求或按原键重试。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function lookup(){if(pending)return;pending=prepareCommand('lookupPatient','POST','/api/v1/patients/lookup',{patient_number:number.value,date_of_birth:birth.value,verification_basis:{clinic_id:clinic.value,person_confirmed:person.value,service_basis:service.value}});await execute()}
async function submit(){if(pending || (props.action==='no-show' && !absenceConfirmed.value))return;pending=prepareCommand(operation(),'POST',`/api/v1/appointments/${encodeURIComponent(id.value)}/${props.action}`,props.action==='attend'?{verification_reference:reference.value}:{reason:reason.value,verification_reference:reference.value});await execute()}
async function query(){if(!pending)return;try{const result=await api.requestResult<{status:string}>(pending);notice.value=result.status==='SUCCEEDED'?'原请求已成功，请按原键读取当前授权结果。':'尚未确认成功，请保留原键。'}catch(failure){await failed(failure)}}
function invalidate(){reference.value='';patient.value=null;absenceConfirmed.value=false}
function selectPending(row:components['schemas']['AppointmentView']){if(pending || busy.value)return;id.value=row.appointment_id;appointment.value=row;clinic.value=row.clinic_id;invalidate();absenceConfirmed.value=false;reason.value='';error.value='';notice.value=''}
</script>
<template><section><h1>{{titles[action]}}</h1><p>{{action==='attend'?'仅授权前台核实本人后办理，患者不能自助确认到诊。':action==='no-show'?'时隙已结束也不自动认定爽约，必须由前台核实未到诊事实后登记。':'开始前患者可自助取消；开始后至时隙结束前由前台核实代办，停诊及已结束按各自流程处理。'}}</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询原请求</button><button :disabled="busy" @click="execute">按原键重试</button></div>
<AppointmentReviewQueue v-if="action==='no-show' &amp;&amp; !unknown" kind="no-show" :key="queueRevision" @select="selectPending" /><fieldset :disabled="busy || unknown"><legend>预约定位</legend><label>预约 ID<input v-model="id" required pattern="[1-9][0-9]*" @input="appointment=null;invalidate()"></label><button v-if="auth.canAccess('RECEPTION','getAppointment')" @click="read">重新读取预约</button></fieldset>
<div v-if="appointment" class="appointment-current"><p>预约 {{appointment.appointment_id}} · {{labels[appointment.status]}} · 诊所 {{appointment.clinic_id}}</p><p>预约时刻：{{new Date(appointment.scheduled_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}（北京时间）</p><p v-if="appointment.attended_at">到诊事实：{{new Date(appointment.attended_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><p v-if="appointment.cancellation_kind">取消分类：{{appointment.cancellation_kind==='PATIENT_CANCEL'?'患者取消':appointment.cancellation_kind==='NO_SHOW'?'核实爽约':'诊所停诊处理'}}</p></div>
<form v-if="auth.canAccess('RECEPTION','getPatient')" @submit.prevent="lookup"><fieldset :disabled="busy || unknown"><legend>{{action==='no-show'?'核实原预约患者及本次服务依据':'核实患者本人及实际服务'}}</legend><label>实际服务诊所 ID<input v-model="clinic" required pattern="[1-9][0-9]*" @input="invalidate"></label><label>原患者编号<input v-model="number" required maxlength="30" @input="invalidate"></label><label>出生日期<input v-model="birth" required type="date" @change="invalidate"></label><label>本次服务依据<input v-model="service" required maxlength="255" @input="invalidate"></label><label class="check"><input v-model="person" type="checkbox" required @change="invalidate">已人工核实本人</label><button>核验本人档案</button></fieldset></form>
<p v-if="patient">已核实：{{patient.full_name}} · {{patient.patient_number}}</p><form @submit.prevent="submit"><fieldset :disabled="busy || unknown"><legend>确认办理</legend><label v-if="action==='no-show'" class="check"><input v-model="absenceConfirmed" type="checkbox" required>已人工核实本次预约确未到诊</label><label>可信核验引用<input v-model="reference" required :readonly="auth.canAccess('RECEPTION','getPatient')"></label><label v-if="action!=='attend'">{{action==='no-show'?'未到诊核实依据及原因':'患者取消原因'}}<input v-model="reason" required maxlength="255"></label><button :disabled="!id || !reference || (action!=='attend' && !reason) || (action==='no-show' && !absenceConfirmed) || (!!appointment && appointment.status!=='SCHEDULED')">{{buttons[action]}}</button></fieldset></form><RouterLink to="/appointment-booking">返回预约管理</RouterLink><RouterLink v-if="action==='attend' && auth.canAccess('RECEPTION','cancelAppointment')" :to="{path:'/appointment-cancellation',query:{appointmentId:id}}">转患者取消核实</RouterLink></section></template>
<style scoped>fieldset{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:20px 0;padding:20px}label{display:grid;gap:7px}input{padding:9px;border:1px solid #bacdc5;border-radius:5px}.check{display:flex;align-items:center}button{padding:10px 16px}.appointment-current{padding:16px;background:#edf5f1;border-left:4px solid #287a60}</style>



